assert subprocess.check_output(['git', '-C', str(REPO), 'rev-parse', 'HEAD'], text=True).strip() == COMMIT
findings = []

def add(id, path, anchor, span, statement, status='code-traced', limits='Static source inspection; not executed in this research.'):
    raw = (REPO / path).read_bytes()
    lines = raw.decode('utf-8-sig').splitlines()
    matches = [i for i, line in enumerate(lines) if anchor in line]
    if not matches:
        raise ValueError((id, path, anchor))
    start = matches[0] + 1
    end = min(start + span - 1, len(lines))
    findings.append(dict(id=id, statement=statement, status=status, source_path=path,
        line_start=start, line_end=end, commit=COMMIT, limits=limits,
        source_sha256=hashlib.sha256(raw).hexdigest(),
        url=f'https://github.com/openclaw/openclaw/blob/{COMMIT}/{path}#L{start}-L{end}'))

